window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[305]={"id":"305","numero":305,"titre":"Tumeurs de l'œsophage","objectifs":[{"id":"305-1","rang":"B","rubrique":"Définition","titre":"Connaître les deux principaux types histologiques de cancer de l’œsophage","contenu":"<p>Deux types histologiques se partagent l'écrasante majorité des cancers de l'œsophage, avec des <span class=\"kw-def\">profils épidémiologiques opposés</span> et des <span class=\"kw-def\">facteurs de risque distincts</span>. <span class=\"kw-clinique\">Les</span> types rares (tumeurs <span class=\"kw-etio\">neuro-endocrines</span>, tumeurs <span class=\"kw-etio\">stromales</span> — léiomyome bénin ou léiomyosarcome) restent anecdotiques en EDN.</p>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th></th>\n            <th><span class=\"kw-clinique\">Carcinome</span> épidermoïde</th>\n            <th>Adénocarcinome</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Histologie</span></strong></td>\n            <td>Dégénérescence de la <span class=\"kw-def\">muqueuse malpighienne</span></td>\n            <td>Dégénérescence d'une <span class=\"kw-def\">muqueuse glandulaire métaplasique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td><span class=\"kw-chiffre\">60-70 %</span></td>\n            <td><span class=\"kw-chiffre\">20-40 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Tendance d'<span class=\"kw-def\">incidence</span></strong></td>\n            <td>En <span class=\"kw-clinique\">diminution</span> (recul OH-<span class=\"kw-etio\">tabac</span>)</td>\n            <td>En <span class=\"kw-clinique\">forte augmentation</span> (épidémie <span class=\"kw-etio\">obésité</span>-<span class=\"kw-clinique\">RGO</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Localisation préférentielle</strong></td>\n            <td>Tout l'œsophage, prédomine aux <span class=\"kw-clinique\">2/3 supérieurs</span></td>\n            <td>Prédomine au <span class=\"kw-clinique\">1/3 inférieur</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Facteurs de risque</span> clés</strong></td>\n            <td>\n              <strong>Toxiques :</strong> <span class=\"kw-etio\">alcool</span> <span class=\"kw-chiffre\">×20</span> ; <span class=\"kw-etio\">tabac</span> <span class=\"kw-chiffre\">×5</span> ; synergie OH+<span class=\"kw-etio\">tabac</span> <span class=\"kw-chiffre\">×100</span><br>\n              <strong>ATCD :</strong> cancers des <span class=\"kw-clinique\">VADS</span> ; <span class=\"kw-ttt\">radiothérapie</span> médiastinale<br>\n              <strong>Alimentaire :</strong> boissons chaudes (thé, maté) ; carences protidiques<br>\n              <strong>Lésions précancéreuses :</strong> <span class=\"kw-clinique\">achalasie</span> ; brûlures caustiques ; œsophagite radique ; <span class=\"kw-clinique\">diverticule</span> de Zenker ; <span class=\"kw-clinique\">sclérodermie</span> ; tylose\n            </td>\n            <td>\n              <strong><span class=\"kw-clinique\">RGO</span> chronique :</strong> via <span class=\"kw-etio\">endobrachyœsophage</span> (EBO)<br>\n              <strong>Métaboliques :</strong> <span class=\"kw-clinique\">surpoids/obésité</span> ; <span class=\"kw-clinique\">diabète de type 2</span><br>\n              <strong><span class=\"kw-etio\">Tabac</span> :</strong> rôle discuté selon <span class=\"kw-clinique\">les</span> sources\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"obj-callout warning\">\n        <strong>Distracteur CCB.</strong> « <em><span class=\"kw-clinique\">Helicobacter pylori</span></em> est associé au cancer de l'œsophage » = <span class=\"kw-alerte\">FAUX</span>. <em><span class=\"kw-clinique\">H. pylori</span></em> est lié au cancer de l'<span class=\"kw-clinique\">estomac</span> (adénocarcinome gastrique, lymphome MALT), pas à celui de l'œsophage. <span class=\"kw-clinique\">Confusion</span> classique en QCM.\n      </div>\n\n      <div class=\"obj-callout\">\n        <strong>Focus EBO (endobrachyœsophage / œsophage de Barrett).</strong> Métaplasie glandulaire cylindrique du 1/3 distal, cicatrisation pathologique d'une œsophagite peptique sur <span class=\"kw-clinique\">RGO chronique</span>. Présent chez <span class=\"kw-chiffre\">10-20 %</span> des sujets <span class=\"kw-clinique\">RGO</span>. Multiplie le risque d'adénocarcinome par <span class=\"kw-chiffre\">×30-100</span> par rapport à la population générale — c'est le <span class=\"kw-alerte\">principal facteur de risque d'adénocarcinome œsophagien</span>. Séquence d'<span class=\"kw-clinique\">évolution</span> : RGO → œsophagite → EBO (métaplasie sans dysplasie) → dysplasie bas <span class=\"kw-def\">grade</span> → haut grade → adénocarcinome (risque <span class=\"kw-chiffre\">&lt; 1 %/an</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale · 303 — Tumeur estomac</em></p>","frequence":2},{"id":"305-2","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales lésions augmentant le risque de survenue ultérieure d’un cancer de l’œsophage","contenu":"<p><span class=\"kw-clinique\">Les</span> FdR du cancer œsophagien se déclinent selon le type histologique. Lien <span class=\"kw-def\">dose-dépendant</span> pour les toxiques. Cet objectif de <strong>rang A</strong> est central — savoir lister les FdR du <span class=\"kw-clinique\">carcinome</span> épidermoïde (<span class=\"kw-def\">terrain</span> OH-<span class=\"kw-etio\">tabac</span>) ET de l'adénocarcinome (terrain EBO/<span class=\"kw-etio\">obésité</span>) est un attendu de l'EDN.</p>\n\n      <h4><span class=\"kw-clinique\">Carcinome</span> épidermoïde — <span class=\"kw-etio\">alcool</span> + <span class=\"kw-etio\">tabac</span> dominent</h4>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th>Catégorie</th>\n            <th>Facteur</th>\n            <th>Risque relatif</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td rowspan=\"3\"><strong>Toxiques (++)</strong></td>\n            <td><span class=\"kw-clinique\">Alcool chronique</span></td>\n            <td><span class=\"kw-chiffre\">×20</span> (alcools forts chauds majorent)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Tabagisme actif</span></td>\n            <td><span class=\"kw-chiffre\">×5</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Synergie alcool + tabac</span></td>\n            <td><span class=\"kw-chiffre\">×100</span> — retrouvée dans <span class=\"kw-chiffre\">90 %</span> des CE</td>\n          </tr>\n          <tr>\n            <td><strong>ATCD oncologiques</strong></td>\n            <td>Cancer des <span class=\"kw-clinique\">VADS</span></td>\n            <td><span class=\"kw-chiffre\">×30</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Iatrogène</span></strong></td>\n            <td><span class=\"kw-ttt\">Radiothérapie</span> médiastinale (lymphome, Hodgkin, sein irradié)</td>\n            <td>Latence longue (années)</td>\n          </tr>\n          <tr>\n            <td rowspan=\"3\"><strong>Alimentaire</strong></td>\n            <td>Boissons chaudes (thé, <span class=\"kw-etio\">maté chaud — Amérique du Sud</span>)</td>\n            <td>Effet thermique répété</td>\n          </tr>\n          <tr>\n            <td>Carences <span class=\"kw-bio\">protidiques</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td>Syndrome de <span class=\"kw-etio\">Plummer-Vinson / Kelly-Paterson</span> (<span class=\"kw-clinique\">dysphagie</span> sidéropénique, carence Fe)</td>\n            <td>Population scandinave</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">HPV</span></strong></td>\n            <td>Rôle discuté en l'absence d'intoxication OH-<span class=\"kw-etio\">tabac</span></td>\n            <td>Controversé</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-clinique\">Carcinome</span> épidermoïde — lésions précancéreuses ⚠️</h4>\n\n      <p>Lésions à <span class=\"kw-alerte\">risque de dégénérescence tardive</span> (latence parfois &gt; 10-<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>20</span> ans</span>) :</p>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th><span class=\"kw-clinique\">Lésion</span> précancéreuse</th>\n            <th>Mécanisme / commentaire</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Achalasie</span></td>\n            <td>Méga-œsophage idiopathique — stase alimentaire chronique sur défaut de relâchement du SIO</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Brûlures caustiques</span></td>\n            <td>Ingestion accidentelle ou volontaire — cicatrisation pathologique, sténose, latence longue</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Œsophagite radique</span></td>\n            <td>ATCD d'<span class=\"kw-clinique\">irradiation</span> médiastinale (lymphome, Hodgkin, cancer du sein irradié)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Diverticule de Zenker</span></td>\n            <td><span class=\"kw-clinique\">Diverticule</span> pharyngo-œsophagien postérieur — stase alimentaire chronique au-dessus du SSO</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Sclérodermie</span></td>\n            <td>Atteinte motrice œsophagienne avec perte de péristaltisme → <span class=\"kw-clinique\">RGO</span> chronique sévère</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Tylose</span></td>\n            <td>Kératodermie palmoplantaire — <span class=\"kw-etio\">génétique</span> rare (mutation <em>RHBDF2</em>), risque <span class=\"kw-etio\">tumoral</span> majeur</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Adénocarcinome — EBO et <span class=\"kw-def\">terrain</span> métabolique</h4>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th>Facteur</th>\n            <th>Mécanisme / commentaire</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">EBO (endobrachyœsophage)</span></td>\n            <td>FdR <strong>principal</strong> ; risque <span class=\"kw-chiffre\">×30-100</span> ; cause = <span class=\"kw-clinique\">RGO chronique</span> → métaplasie intestinale → dysplasie → ADK</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Surpoids / obésité</span></td>\n            <td>Excès alimentaire ; calories animales ; <span class=\"kw-etio\">sédentarité</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Diabète de type 2</span></td>\n            <td>Composante du <span class=\"kw-def\">syndrome métabolique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Tabac</span></td>\n            <td>Rôle discuté (HGE) — moindre que pour le CE</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"obj-callout warning\">\n        <strong>Cancers associés synchrones.</strong> Sur <span class=\"kw-def\">terrain</span> OH-<span class=\"kw-etio\">tabac</span>, <span class=\"kw-chiffre\">20 %</span> des carcinomes épidermoïdes œsophagiens ont un cancer synchrone des <span class=\"kw-clinique\">VADS</span> ou <span class=\"kw-clinique\">broncho-pulmonaire</span>. D'où la pan-<span class=\"kw-imagerie\">endoscopie</span> VADS + <span class=\"kw-imagerie\">fibroscopie</span> trachéo-bronchique systématiques dans le <span class=\"kw-def\">bilan d'extension</span> du CE — pas un caprice méthodologique.\n      </div>\n\n      <div class=\"obj-callout\">\n        <strong><span class=\"kw-def\">Surveillance</span> EBO.</strong> Par <span class=\"kw-imagerie\">EOGD</span> avec <span class=\"kw-bio\">biopsies</span> étagées multiples — rythme conditionné par la hauteur de l'EBO et la présence d'une dysplasie. Sans dysplasie : tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-5 ans</span>. Dysplasie bas <span class=\"kw-def\">grade</span> : contrôle à <span class=\"kw-chiffre\">2-3 mois</span> sous <span class=\"kw-ttt\">IPP</span> double dose, puis tous les <span class=\"kw-chiffre\">6 mois</span> la première année. Dysplasie haut grade : contrôle à <span class=\"kw-chiffre\">M1</span>, puis si confirmée → <span class=\"kw-ttt\">mucosectomie endoscopique</span> ou <span class=\"kw-ttt\">chirurgie</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale · 298 — Tumeur cavité buccale-nasosinusienne-cavum-VADS · 209 — <span class=\"kw-etio\">BPCO</span> · 304 — Tumeur du foie</em></p>","frequence":0},{"id":"305-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’incidence et la prévalence des cancers de l’œsophage en France","contenu":"<p>Cancer rare mais grave : <span class=\"kw-chiffre\">2 %</span> de tous <span class=\"kw-clinique\">les</span> cancers et <span class=\"kw-chiffre\">10 %</span> des cancers digestifs en France. Profil démographique très orienté (homme âgé OH-tabagique), mais <span class=\"kw-clinique\">évolution</span> récente vers une <span class=\"kw-clinique\">stabilité voire augmentation chez la femme</span> et une forte montée de l'adénocarcinome.</p>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th>Paramètre</th>\n            <th>Donnée chiffrée (France, 2018)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Incidence</span></strong></td>\n            <td><span class=\"kw-chiffre\">5 400</span> nouveaux cas/an — <span class=\"kw-chiffre\">2 %</span> de tous <span class=\"kw-clinique\">les</span> cancers, <span class=\"kw-chiffre\">10 %</span> des cancers digestifs</td>\n          </tr>\n          <tr>\n            <td><strong>Tendance</strong></td>\n            <td>En <span class=\"kw-clinique\">diminution progressive</span> depuis <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>30</span> ans</span> chez l'homme (recul OH) ; <span class=\"kw-alerte\">stable voire augmente chez la femme</span></td>\n          </tr>\n          <tr>\n            <td><strong>Régions <span class=\"kw-clinique\">les</span> plus touchées</strong></td>\n            <td><span class=\"kw-clinique\">Nord</span> et <span class=\"kw-clinique\">Nord-Ouest</span> (Bretagne, Normandie) — mais c'est là aussi que la baisse d'<span class=\"kw-def\">incidence</span> est la plus rapide</td>\n          </tr>\n          <tr>\n            <td><strong>Sex-ratio</strong></td>\n            <td>Prédominance masculine <span class=\"kw-chiffre\">4 H / 1 F</span></td>\n          </tr>\n          <tr>\n            <td><strong>Âge moyen au diagnostic</strong></td>\n            <td><span class=\"kw-chiffre\">65 ans</span> chez l'homme · <span class=\"kw-chiffre\">70 ans</span> chez la femme</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Mortalité</span></strong></td>\n            <td><span class=\"kw-chiffre\">3 700</span> décès/an — en diminution</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span> global</strong></td>\n            <td>Sombre 🏴‍☠️ : survie <span class=\"kw-chiffre\">10-15 %</span> à <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> ans</span> tous stades confondus (car &gt; <span class=\"kw-chiffre\">60 %</span> des cas diagnostiqués à un <span class=\"kw-def\">stade</span> localement avancé ou métastatique)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span> par <span class=\"kw-def\">stade</span></strong></td>\n            <td>\n              <strong>Localisé :</strong> survie &lt; <span class=\"kw-chiffre\">40 %</span> à <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> ans</span><br>\n              <strong>Métastatique :</strong> survie &lt; <span class=\"kw-chiffre\">5 %</span> à 5 ans\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Repères mondiaux</h4>\n\n      <ul>\n        <li><span class=\"kw-def\">Incidence</span> mondiale : <span class=\"kw-chiffre\">480 000</span> nouveaux cas/an, très variable selon <span class=\"kw-clinique\">les</span> régions</li>\n        <li><strong>Forte <span class=\"kw-def\">incidence</span> :</strong> Asie (Chine, Iran)</li>\n        <li><strong>Moyenne :</strong> Europe</li>\n        <li><strong>Faible :</strong> Afrique, États-Unis</li>\n      </ul>\n\n      <div class=\"obj-callout\">\n        <strong>Pourquoi ces chiffres comptent en QCM.</strong> Le <span class=\"kw-def\">pronostic</span> sombre justifie une <span class=\"kw-clinique\">prise en charge multidisciplinaire en centre expert</span> dès le diagnostic, et explique pourquoi la <span class=\"kw-ttt\">chirurgie</span> n'est envisageable que pour <span class=\"kw-chiffre\">10-30 %</span> des patients (souvent diagnostic tardif). Le couple OH-<span class=\"kw-etio\">tabac</span> concentre <span class=\"kw-chiffre\">90 %</span> des CE — ce qui fait du <span class=\"kw-ttt\">sevrage</span> et du <span class=\"kw-def\">dépistage</span> par <span class=\"kw-imagerie\">EOGD</span> chez <span class=\"kw-clinique\">les</span> sujets à risque les seuls leviers de prévention pertinents.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":1},{"id":"305-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales circonstances de découverte et les manifestations cliniques du cancer de l’œsophage","contenu":"<p>Cet objectif de <strong>rang A</strong> est fondamental : c'est le scénario type d'un cas clinique EDN. Le <span class=\"kw-alerte\">drapeau rouge</span> à connaître est la <span class=\"kw-alerte\">dysphagie organique progressive permanente sans rétrocession</span> chez un sujet OH-tabagique → <span class=\"kw-imagerie\">FOGD</span> en <span class=\"kw-alerte\">urgence</span> relative. La sémiologie d'extension (Troisier, voix bitonale, fausses-routes) est piégée par sa réinterprétation TNM (la dernière version classe certains ganglions comme N et non M).</p>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th>Type de signe</th>\n            <th>Détail</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Dépistage</span> chez asymptomatique</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">EOGD</span> de <span class=\"kw-def\">dépistage</span> chez sujets <span class=\"kw-clinique\">alcoolo-tabagiques</span><br>\n              EOGD de <span class=\"kw-def\">surveillance</span> de l'<span class=\"kw-clinique\">EBO</span> : tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-5 ans</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes généraux</strong></td>\n            <td><span class=\"kw-clinique\">AEG</span> (parfois unique signe d'appel) : <span class=\"kw-clinique\">amaigrissement</span> souvent &gt; <span class=\"kw-chiffre\">5-10 %</span> du poids ; <span class=\"kw-clinique\">asthénie</span> ; <span class=\"kw-clinique\">anorexie</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Dysphagie</span> organique (signe principal)</strong></td>\n            <td>\n              <strong>Horaire :</strong> <span class=\"kw-alerte\">permanente, sans rétrocession</span> (≠ <span class=\"kw-clinique\">dysphagie</span> fonctionnelle paradoxale ou intermittente)<br>\n              <strong>Installation :</strong> progressive — accrochage intermittent aux solides (viande, <span class=\"kw-clinique\">croûte</span> de pain) → dysphagie aux solides → dysphagie aux liquides → <span class=\"kw-alerte\">aphagie complète</span> avec stase salivaire<br>\n              Toute dysphagie progressive impose une <span class=\"kw-imagerie\">FOGD</span> avec <span class=\"kw-bio\">biopsies</span> de toute <span class=\"kw-clinique\">lésion</span> suspecte\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes associés</strong></td>\n            <td>\n              <strong>Digestifs :</strong> <span class=\"kw-clinique\">régurgitations</span> ; <span class=\"kw-clinique\">hoquet</span> ; <span class=\"kw-clinique\">odynophagie</span> ; <span class=\"kw-clinique\">haleine fétide</span> (stase alimentaire)<br>\n              <strong>Douleurs :</strong> <span class=\"kw-clinique\">thoraciques</span> ou <span class=\"kw-clinique\">dorsales</span><br>\n              <strong><span class=\"kw-etio\">Hémorragique</span> :</strong> <span class=\"kw-alerte\">hématémèse</span> ou <span class=\"kw-alerte\">méléna</span> (plus rare)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Extension locale (syndromes médiastinaux)</strong></td>\n            <td>\n              <strong>Récurrentielle gauche :</strong> <span class=\"kw-clinique\">dysphonie / voix bitonale</span> par paralysie de la corde vocale gauche<br>\n              <strong>Pulmonaire :</strong> surinfections respiratoires à répétition<br>\n              <strong>Douloureuse :</strong> douleurs rétro-sternales ou inter-scapulaires<br>\n              <strong><span class=\"kw-clinique\">Toux</span> à la déglutition :</strong> deux mécanismes — <span class=\"kw-alerte\">fistule trachéo/broncho-œsophagienne</span> OU fausse-route par paralysie corde vocale gauche\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Extension métastatique</strong></td>\n            <td>\n              <strong>Ganglionnaire :</strong> <span class=\"kw-clinique\">adénopathie</span> sus-claviculaire gauche (<span class=\"kw-def\">ganglion de Troisier</span>)<br>\n              <strong>Hépatique :</strong> <span class=\"kw-clinique\">douleurs abdominales</span> ; <span class=\"kw-clinique\">hépatomégalie</span> nodulaire<br>\n              <strong>Pulmonaire :</strong> <span class=\"kw-clinique\">dyspnée</span> ; <span class=\"kw-imagerie\">épanchement pleural</span><br>\n              <strong>Osseuse :</strong> douleurs osseuses inflammatoires ; hypercalcémie\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic positif</span></strong></td>\n            <td>\n              <span class=\"kw-imagerie\">EOGD</span> avec <span class=\"kw-clinique\">biopsies multiples</span> — patient à jeun, AL ou AG, après bilan d'hémostase<br>\n              <strong>À recueillir :</strong> aspect ; caractère franchissable ou non ; distance par rapport aux arcades dentaires ; distance par rapport à la ligne Z ; <span class=\"kw-def\">type histologique</span><br>\n              <strong>Cancers superficiels :</strong> colorations bleu et Lugol, colorations virtuelles (NBI)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"obj-callout warning\">\n        <strong>Piège TNM (à connaître).</strong> Dans la dernière <span class=\"kw-def\">classification</span> TNM, le <span class=\"kw-def\">ganglion de Troisier</span> sus-claviculaire gauche est classé <span class=\"kw-alerte\">loco-régional (N) — pas métastatique (M)</span> pour <span class=\"kw-clinique\">les</span> carcinomes du <span class=\"kw-clinique\">1/3 supérieur</span>. De même, les <span class=\"kw-clinique\">adénopathies cœliaques</span> sont classées <strong>régionales</strong>, plus comme des métastases. Toujours préciser la localisation <span class=\"kw-etio\">tumorale</span> avant d'interpréter la TNM.\n      </div>\n\n      <div class=\"obj-callout danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> <span class=\"kw-clinique\">Dysphagie</span> progressive aux solides + <span class=\"kw-clinique\">perte de poids</span> + <span class=\"kw-def\">terrain</span> OH-<span class=\"kw-etio\">tabac</span> → <span class=\"kw-alerte\">FOGD avec biopsies en urgence relative</span>. Ne jamais attribuer une dysphagie progressive permanente à un RGO ou à une œsophagite sans avoir éliminé la tumeur par <span class=\"kw-imagerie\">endoscopie</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale · 274 — <span class=\"kw-clinique\">Vomissements</span></em></p>","frequence":0},{"id":"305-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration par imagerie d’une tumeur de l’œsophage","contenu":"<p>Stratégie d'imagerie hiérarchisée : la <span class=\"kw-imagerie\">FOGD avec biopsies</span> confirme le diagnostic, puis le <span class=\"kw-imagerie\">TDM TAP injecté</span> assure le <span class=\"kw-def\">bilan d'extension</span> de référence. <span class=\"kw-clinique\">Les</span> autres examens (<span class=\"kw-imagerie\">TEP-TDM</span>, écho-<span class=\"kw-imagerie\">endoscopie</span>, <span class=\"kw-imagerie\">fibroscopie</span> trachéo-bronchique, <span class=\"kw-imagerie\">IRM</span> cérébrale, <span class=\"kw-imagerie\">scintigraphie</span> osseuse) sont indiqués <strong>en fonction du type histologique, de la localisation et de la situation clinique</strong> — pas en routine systématique. Toute imagerie doit servir à <span class=\"kw-def\">orienter une décision thérapeutique</span> (<span class=\"kw-def\">RCP</span>), sinon elle n'a pas lieu d'être.</p>\n\n      <h4>Hiérarchisation des examens (selon HGE)</h4>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th>Étape</th>\n            <th>Examen</th>\n            <th>Indication</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Diagnostic initial</strong></td>\n            <td><span class=\"kw-imagerie\">FOGD avec biopsies</span></td>\n            <td>Confirme le diagnostic histologique (CE <span class=\"kw-bio\">vs</span> ADK)</td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"kw-def\">Bilan d'extension</span></strong></td>\n            <td><span class=\"kw-imagerie\">TDM TAP injecté</span></td>\n            <td><strong>Systématique</strong> — local, loco-régional, à distance</td>\n          </tr>\n          <tr>\n            <td rowspan=\"2\"><strong>3. Selon résultats <span class=\"kw-imagerie\">TDM</span></strong></td>\n            <td><span class=\"kw-imagerie\">TEP-TDM au 18-FDG</span></td>\n            <td>Avant traitement à visée curative ; si doute sur <span class=\"kw-clinique\">lésion</span> métastatique au <span class=\"kw-imagerie\">TDM</span> ; recherche d'une CI opératoire ; ciblage <span class=\"kw-ttt\">radiothérapie</span> ; évaluation réponse à RCT néo-adjuvante</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Écho-endoscopie œsophagienne</span></td>\n            <td>Si tumeur de <span class=\"kw-clinique\">petite taille</span> ou franchissable ; précise T et N loco-régional ; différencie superficiel intra-muqueux/sous-muqueux ; <span class=\"kw-bio\">biopsies</span> trans-œsophagiennes d'ADP suspectes — <span class=\"kw-alerte\">PAS indiquée</span> si tumeur déjà manifestement avancée ou métastatique</td>\n          </tr>\n          <tr>\n            <td><strong>4. Selon type histologique</strong></td>\n            <td>Voir tableau ci-dessous</td>\n            <td>Différences CE / ADK</td>\n          </tr>\n          <tr>\n            <td rowspan=\"4\"><strong>5. Examens ciblés (point d'appel)</strong></td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span></td>\n            <td>Avant <span class=\"kw-ttt\">chirurgie</span> ; ou point d'appel cérébral</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Scintigraphie osseuse</span></td>\n            <td>Point d'appel osseux ; <strong>non utile</strong> si <span class=\"kw-imagerie\">TEP-TDM</span> déjà réalisé</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie cervicale</span> ± cytoponction</td>\n            <td>ADP cervicale ou sus-claviculaire suspecte</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Transit œsophagien</span></td>\n            <td>Non systématique — précise la <span class=\"kw-clinique\">localisation</span> et la <span class=\"kw-clinique\">hauteur</span> <span class=\"kw-etio\">tumorale</span>, ainsi que l'extension sur l'estomac ; parfois demandé avant la <span class=\"kw-ttt\">chirurgie</span></td>\n          </tr>\n          <tr>\n            <td><strong>6. Spécifique ADK jonction</strong></td>\n            <td><span class=\"kw-imagerie\">Laparoscopie exploratrice</span></td>\n            <td>ADK œsophagien ou de la jonction œsogastrique chez patient candidat à un traitement curatif, en l'absence d'extension péritonéale évidente au <span class=\"kw-imagerie\">TDM</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Bilan d'extension</span> selon type histologique</h4>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th></th>\n            <th><span class=\"kw-clinique\">Carcinome</span> épidermoïde</th>\n            <th>Adénocarcinome</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Systématique</strong></td>\n            <td>\n              <strong>Imagerie :</strong> <span class=\"kw-imagerie\">TDM</span> TAP injecté<br>\n              <strong>ORL :</strong> naso-<span class=\"kw-imagerie\">fibroscopie</span> ; pan-<span class=\"kw-imagerie\">endoscopie</span> VADS<br>\n              <strong>Bronchique :</strong> <span class=\"kw-imagerie\">fibroscopie</span> trachéo-bronchique\n            </td>\n            <td><span class=\"kw-imagerie\">TDM</span> TAP injecté</td>\n          </tr>\n          <tr>\n            <td><strong>Selon la situation</strong></td>\n            <td>\n              <strong>Si 1/3 supérieur :</strong> <span class=\"kw-imagerie\">TDM</span> cervicale injectée<br>\n              <strong>Avant traitement curatif :</strong> <span class=\"kw-imagerie\">TEP-TDM</span> 18-FDG<br>\n              <strong>Si petite taille :</strong> écho-<span class=\"kw-imagerie\">endoscopie</span> œsophagienne\n            </td>\n            <td>\n              <strong>Si fumeur :</strong> naso-<span class=\"kw-imagerie\">fibroscopie</span> + pan-<span class=\"kw-imagerie\">endoscopie</span> VADS<br>\n              <strong>Si 2/3 supérieur ou fumeur :</strong> <span class=\"kw-imagerie\">fibroscopie</span> trachéo-bronchique<br>\n              <strong>Si petite taille :</strong> écho-<span class=\"kw-imagerie\">endoscopie</span> œsophagienne<br>\n              <strong>Si ADK jonction métastatique :</strong> <span class=\"kw-bio\">immunohistochimie HER2</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Trois territoires explorés par le <span class=\"kw-def\">bilan d'extension</span></h4>\n\n      <ul>\n        <li><strong>Local (extension pariétale T) :</strong> <span class=\"kw-imagerie\">écho-endoscopie</span> ; <span class=\"kw-imagerie\">TDM</span> thoracique</li>\n        <li><strong>Loco-régional (ADP médiastinales, organes de voisinage) :</strong> <span class=\"kw-imagerie\">TDM thoracique</span> ; écho-<span class=\"kw-imagerie\">endoscopie</span> ; <span class=\"kw-imagerie\">fibroscopie</span> trachéo-bronchique (1/3 moyen et supérieur)</li>\n        <li><strong>À distance (ADP cervicales/cœliaques, métastases, 2<sup>e</sup> cancer synchrone) :</strong> <span class=\"kw-imagerie\">TDM TAP</span> ; <span class=\"kw-imagerie\">TEP-TDM</span> ; marqueurs (<span class=\"kw-bio\">SCC</span> pour CE, <span class=\"kw-bio\">ACE/CA19-9</span> pour ADK) ; pan-<span class=\"kw-imagerie\">endoscopie</span> VADS + <span class=\"kw-imagerie\">fibroscopie</span> trachéo-bronchique si CE</li>\n      </ul>\n\n      <div class=\"obj-callout\">\n        <strong>Marqueurs tumoraux — uniquement pour le <span class=\"kw-def\">suivi</span>.</strong> Aucune indication diagnostique. Utilisés seulement s'ils étaient <span class=\"kw-clinique\">élevés initialement</span> : <span class=\"kw-bio\">SCC</span> pour <span class=\"kw-clinique\">les</span> cancers épidermoïdes ; <span class=\"kw-bio\">ACE et CA19-9</span> pour les adénocarcinomes. Piège QCM classique : « quel marqueur <span class=\"kw-etio\">tumoral</span> pour le diagnostic du cancer de l'œsophage ? » → réponse = aucun, le diagnostic est <span class=\"kw-clinique\">histologique</span> (<span class=\"kw-imagerie\">FOGD</span> + <span class=\"kw-bio\">biopsies</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 293 — Anapath</em></p>","frequence":0},{"id":"305-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de la fibroscopie œsogastrique","contenu":"<p>La <span class=\"kw-imagerie\">fibroscopie œsogastrique (FOGD ou EOGD)</span> est l'examen pivot de la pathologie œsophagienne — diagnostic, <span class=\"kw-def\">dépistage</span>, <span class=\"kw-def\">surveillance</span> des lésions précancéreuses, suivi post-traitement. Toute <span class=\"kw-clinique\">dysphagie</span> organique impose une <span class=\"kw-imagerie\">FOGD</span> avec <span class=\"kw-bio\">biopsies</span> de toute <span class=\"kw-clinique\">lésion</span> suspecte. Son rendement diagnostique dépend de la qualité de préparation et de la lecture des données recueillies (distance aux arcades, franchissabilité, ligne Z).</p>\n\n      <h4>Indications de la <span class=\"kw-imagerie\">FOGD</span></h4>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th>Indication</th>\n            <th>Précisions</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic positif</span></strong> (gold standard)</td>\n            <td>\n              Toute <span class=\"kw-clinique\">dysphagie organique</span> progressive permanente sans rétrocession<br>\n              <strong><span class=\"kw-bio\">Biopsies</span> multiples</strong> systématiques de toute <span class=\"kw-clinique\">lésion</span> suspecte<br>\n              Permet d'établir le <span class=\"kw-def\">type histologique</span> (CE <span class=\"kw-bio\">vs</span> ADK)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Dépistage</span> chez asymptomatique</strong></td>\n            <td>\n              Sujets <span class=\"kw-clinique\">alcoolo-tabagiques</span> (<span class=\"kw-def\">terrain</span> à risque de <span class=\"kw-clinique\">carcinome</span> épidermoïde)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Surveillance</span> d'un EBO</strong></td>\n            <td>\n              <strong>Sans dysplasie :</strong> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-5 ans</span> (rythme selon hauteur de l'EBO)<br>\n              <strong>Dysplasie bas <span class=\"kw-def\">grade</span> suspectée :</strong> contrôle à <span class=\"kw-chiffre\">2-3 mois</span> sous <span class=\"kw-ttt\">IPP</span> double dose<br>\n              <strong>Dysplasie bas grade confirmée :</strong> tous les <span class=\"kw-chiffre\">6 mois</span> la 1<sup>re</sup> année, puis <span class=\"kw-chiffre\">1×/an</span><br>\n              <strong>Dysplasie haut grade :</strong> contrôle à <span class=\"kw-chiffre\">M1</span>, puis si confirmée → <span class=\"kw-ttt\">mucosectomie</span> ou <span class=\"kw-ttt\">chirurgie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Suivi</span> post-traitement curatif</strong></td>\n            <td>\n              <strong>Après <span class=\"kw-ttt\">chirurgie</span> :</strong> <span class=\"kw-imagerie\">FOGD</span> à <span class=\"kw-chiffre\">2 ans</span><br>\n              <strong>Après RCT exclusive :</strong> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">4 mois</span> pendant <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> ans</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cancers superficiels / lésions précancéreuses</strong></td>\n            <td>\n              Colorations <span class=\"kw-clinique\">bleu et Lugol</span> ; colorations virtuelles (<span class=\"kw-clinique\">NBI</span> — narrow band imaging) pour le diagnostic difficile\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Conditions de réalisation</h4>\n\n      <ul>\n        <li>Patient à <span class=\"kw-clinique\">jeun</span></li>\n        <li>Information du patient (procédure, risques, <span class=\"kw-bio\">biopsies</span>)</li>\n        <li>Vérification du <span class=\"kw-bio\">bilan d'hémostase</span> avant <span class=\"kw-bio\">biopsies</span></li>\n        <li>Sous <span class=\"kw-clinique\">anesthésie locale</span> (xylocaïne pharyngée) ou <span class=\"kw-clinique\">anesthésie générale</span> selon contexte</li>\n      </ul>\n\n      <h4>Données à recueillir lors de la <span class=\"kw-imagerie\">FOGD</span></h4>\n\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr>\n            <th>Item</th>\n            <th>Détail / piège</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Aspect macroscopique</strong></td>\n            <td>Ulcéro-bourgeonnant, infiltrant, sténosant ; étendue sur la circonférence</td>\n          </tr>\n          <tr>\n            <td><strong>Caractère franchissable</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Tumeur non franchissable par l'endoscope = très souvent ≥ T3</span> selon la TNM\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Topographie</strong></td>\n            <td>\n              <strong>Distance aux arcades dentaires :</strong> 1/3 sup <span class=\"kw-chiffre\">20-25 cm</span> · 1/3 moyen <span class=\"kw-chiffre\">25-32 cm</span> · 1/3 inf <span class=\"kw-chiffre\">32-40 cm</span><br>\n              <strong>Distance à la ligne Z :</strong> jonction muqueuses œsophagienne / gastrique (cardia)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Biopsies</span> multiples</strong></td>\n            <td>\n              <strong>Type histologique</strong> (CE <span class=\"kw-bio\">vs</span> ADK)<br>\n              <strong><span class=\"kw-def\">Grade</span> OMS</strong> de <span class=\"kw-bio\">différenciation</span><br>\n              <strong><span class=\"kw-bio\">Immunohistochimie</span> HER2</strong> si ADK de la jonction œsogastrique métastatique (impact thérapeutique — <span class=\"kw-ttt\">trastuzumab</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"obj-callout warning\">\n        <strong>Tumeur non franchissable.</strong> Drapeau pronostique fort — quasi-systématiquement <span class=\"kw-alerte\">≥ T3</span>, écho-<span class=\"kw-imagerie\">endoscopie</span> alors souvent non possible ou peu contributive. Préfère le <span class=\"kw-imagerie\">TDM</span> injecté + <span class=\"kw-imagerie\">TEP-TDM</span> pour le <span class=\"kw-def\">bilan d'extension</span>.\n      </div>\n\n      <div class=\"obj-callout\">\n        <strong>Cardia anatomique et <span class=\"kw-def\">classification</span> de Siewert.</strong> Pour <span class=\"kw-clinique\">les</span> tumeurs de la jonction œsogastrique, la distance entre épicentre <span class=\"kw-etio\">tumoral</span> et cardia détermine le type Siewert (I = 5 à 1 cm au-dessus ; II = 1 cm au-dessus à 2 cm en dessous ; III = 2 à 5 cm en dessous). Dernière classification TNM : tous les Siewert sont classés selon la TNM de l'<span class=\"kw-def\">œsophage</span>, plus de l'estomac.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale · 293 — Anapath · 303 — Tumeur estomac</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/oesophageal-carcinoma-1","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/esophagus-2","label":"radiopaedia.org"}]}],"astuces":[],"cards":[{"i":"2caf69c3fa0a","n":305,"o":"305-2","u":"Etiologies","t":"Connaître les principales lésions augmentant le risque de survenue ultérieure d’un cancer de l’œsophage","q":"Quels sont les principaux facteurs de risque de l'adénocarcinome de l'œsophage ?","a":"<p>Les principaux facteurs de risque de l'adénocarcinome de l'œsophage sont :</p><ul><li>L'<strong>endobrachyoesophage (EBO)</strong>, qui est le facteur de risque principal (risque multiplié par 30-100), résultant d'un RGO chronique.</li><li>Le <strong>surpoids / obésité</strong>.</li><li>Le <strong>diabète de type 2</strong>, composante du syndrome métabolique.</li><li>Le tabac a un rôle discuté, moindre que pour le carcinome épidermoïde.</li></ul>"},{"i":"f0793945bc8f","n":305,"o":"305-2","u":"Etiologies","t":"Connaître les principales lésions augmentant le risque de survenue ultérieure d’un cancer de l’œsophage","q":"Quelles sont les lésions précancéreuses du carcinome épidermoïde de l'œsophage ?","a":"<p>Les lésions précancéreuses du carcinome épidermoïde de l'œsophage, avec une latence parfois supérieure à 10-20 ans, sont :</p><ul><li>L'<strong>achalasie</strong> (méga-œsophage idiopathique).</li><li>Les <strong>brûlures caustiques</strong> de l'œsophage.</li><li>L'<strong>œsophagite radique</strong> (suite à une irradiation médiastinale).</li><li>Le <strong>diverticule de Zenker</strong>.</li><li>La <strong>sclérodermie</strong> avec atteinte motrice œsophagienne et RGO chronique sévère.</li><li>La <strong>tylose</strong> (kératodermie palmoplantaire).</li></ul>"},{"i":"f4a8451bb5b6","n":305,"o":"305-2","u":"Etiologies","t":"Connaître les principales lésions augmentant le risque de survenue ultérieure d’un cancer de l’œsophage","q":"Quels sont les principaux facteurs de risque du carcinome épidermoïde de l'œsophage ?","a":"<p>Les principaux facteurs de risque du carcinome épidermoïde de l'œsophage sont :</p><ul><li>Les <strong>toxiques</strong> : l'alcool chronique (risque multiplié par 20, majoré par les alcools forts et chauds) et le tabagisme actif (risque multiplié par 5). La <strong>synergie alcool + tabac</strong> est majeure (risque multiplié par 100) et retrouvée dans 90% des carcinomes épidermoïdes.</li><li>Les <strong>antécédents oncologiques</strong> : cancer des VADS ou radiothérapie médiastinale.</li><li>Les <strong>facteurs alimentaires</strong> : boissons très chaudes (thé, maté), carences protidiques (syndrome de Plummer-Vinson/Kelly-Paterson).</li></ul>"},{"i":"115a100f7024","n":305,"o":"305-4","u":"Diagnostic positif","t":"Connaître les principales circonstances de découverte et les manifestations cliniques du cancer de l’œsophage","q":"Quels sont les signes cliniques d'extension métastatique du cancer de l'œsophage par voie ganglionnaire, hépatique, pulmonaire ou osseuse ?","a":"<p>Les signes cliniques d'extension métastatique peuvent être :</p><ul><li><strong>Ganglionnaire</strong> : présence d'une <strong>adénopathie sus-claviculaire gauche (ganglion de Troisier)</strong>. <em>(À noter : dans la dernière classification TNM, le ganglion de Troisier est classé N et non M pour les cancers du 1/3 supérieur)</em>.</li><li><strong>Hépatique</strong> : douleurs abdominales, hépatomégalie nodulaire.</li><li><strong>Pulmonaire</strong> : dyspnée, épanchement pleural.</li><li><strong>Osseuse</strong> : douleurs osseuses inflammatoires, hypercalcémie.</li></ul>"},{"i":"13bb80ce9603","n":305,"o":"305-4","u":"Diagnostic positif","t":"Connaître les principales circonstances de découverte et les manifestations cliniques du cancer de l’œsophage","q":"Comment se caractérise la dysphagie du cancer de l'œsophage et quelle est son évolution classiquement décrite ?","a":"<p>La dysphagie du cancer de l'œsophage est une <strong>dysphagie organique</strong>, caractérisée par :</p><ul><li>Un horaire <strong>permanent</strong>, sans régression.</li><li>Une installation <strong>progressive</strong>, débutant par un \"accrochage\" intermittent aux <strong>solides</strong> (viande, croûte de pain), évoluant vers une dysphagie aux solides puis aux <strong>liquides</strong>, et pouvant aboutir à une <strong>aphagie complète avec stase salivaire</strong>.</li></ul><p>Toute dysphagie progressive doit faire éliminer un cancer de l'œsophage par FOGD avec biopsies.</p>"},{"i":"412e4bfef45c","n":305,"o":"305-4","u":"Diagnostic positif","t":"Connaître les principales circonstances de découverte et les manifestations cliniques du cancer de l’œsophage","q":"Quels sont les signes généraux et les symptômes digestifs associés pouvant accompagner la dysphagie dans le cancer de l'œsophage ?","a":"<p>Les signes généraux sont ceux d'une <strong>altération de l'état général (AEG)</strong>, qui peut être le seul signe d'appel :</p><ul><li><strong>Amaigrissement</strong> souvent supérieur à 5-10% du poids initial.</li><li>Asthénie.</li><li>Anorexie.</li></ul><p>Les symptômes digestifs associés peuvent inclure :</p><ul><li>Régurgitations.</li><li>Hoquet.</li><li>Odynophagie (douleur à la déglutition).</li><li>Haleine fétide (liée à la stase alimentaire).</li></ul>"},{"i":"559349de003c","n":305,"o":"305-4","u":"Diagnostic positif","t":"Connaître les principales circonstances de découverte et les manifestations cliniques du cancer de l’œsophage","q":"Quels sont les signes cliniques d'extension locale du cancer de l'œsophage, liés à l'envahissement des structures médiastinales ?","a":"<p>Les signes cliniques d'extension locale sont majoritairement des <strong>syndromes médiastinaux</strong> :</p><ul><li><strong>Signe neurologique</strong> : <strong>dysphonie / voix bitonale</strong> due à la paralysie de la corde vocale gauche par atteinte du <strong>nerf récurrent gauche</strong> (syndrome récurrentiel gauche).</li><li><strong>Signes respiratoires</strong> : <strong>surinfections respiratoires</strong> à répétition, ou une <strong>toux à la déglutition</strong>.</li><li><strong>Douleurs</strong> : douleurs <strong>rétro-sternales ou inter-scapulaires</strong>.</li></ul>"},{"i":"983f06f2d9ad","n":305,"o":"305-4","u":"Diagnostic positif","t":"Connaître les principales circonstances de découverte et les manifestations cliniques du cancer de l’œsophage","q":"Quelle est la principale circonstance de découverte et le signe d'appel le plus fréquent du cancer de l'œsophage, orientant vers la réalisation d'une endoscopie digestive haute ?","a":"<p>La principale circonstance de découverte est une <strong>dysphagie organique progressive et permanente</strong>, sans régression, chez un patient ayant des antécédents d'<strong>OH-tabagisme</strong>. Cette symptomatologie est un <strong>drapeau rouge</strong> imposant une <strong>fibroscopie œso-gastro-duodénale (FOGD) en urgence relative</strong>.</p>"}]};